-- Run only in the approved lab controller. Everything, including fixtures, rolls back.
begin;
set local statement_timeout='10s';
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','product_feedback','private feedback exists');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.product_feedback'::regclass),'ENABLE and FORCE RLS');
select ok(not exists(select 1 from pg_class c cross join lateral aclexplode(c.relacl) a where c.oid='public.product_feedback'::regclass and a.grantee=0),'PUBLIC has no relation privileges');
select ok(has_table_privilege('service_role','public.product_feedback','SELECT,INSERT,UPDATE,DELETE'),'service CRUD granted');
select ok(not has_table_privilege('service_role','public.product_feedback','TRUNCATE') and not has_table_privilege('service_role','public.product_feedback','REFERENCES') and not has_table_privilege('service_role','public.product_feedback','TRIGGER'),'service has no extra table grants');
-- Existing local actor is a FK only; neither profile nor its metadata is changed.
insert into public.product_feedback(id,profile_id,kind,surface,message) values('b6000000-0000-4000-8000-000000000001','55555555-5555-4555-8555-555555555551','ISSUE','MERCHANT','synthetic SQL feedback');
select is((select version from public.product_feedback where id='b6000000-0000-4000-8000-000000000001'),1,'version defaults to one');
select is((select status::text from public.product_feedback where id='b6000000-0000-4000-8000-000000000001'),'NEW','status defaults NEW');
select ok((select expires_at=created_at+interval '90 days' from public.product_feedback where id='b6000000-0000-4000-8000-000000000001'),'retention defaults ninety days');
set local role anon;
select throws_ok($$select message from public.product_feedback$$,'42501',null,'anon read denied');
select throws_ok($$insert into public.product_feedback(profile_id,kind,surface,message) values('55555555-5555-4555-8555-555555555551','ISSUE','MERCHANT','forbidden')$$,'42501',null,'anon insert denied');
select throws_ok($$update public.product_feedback set status='CLOSED'$$,'42501',null,'anon update denied');
select throws_ok($$delete from public.product_feedback$$,'42501',null,'anon delete denied');
reset role;
set local role authenticated;
select throws_ok($$select message from public.product_feedback where profile_id='55555555-5555-4555-8555-555555555551'$$,'42501',null,'authenticated own marker read denied');
select throws_ok($$insert into public.product_feedback(profile_id,kind,surface,message) values('55555555-5555-4555-8555-555555555551','ISSUE','MERCHANT','forbidden')$$,'42501',null,'authenticated insert denied');
select throws_ok($$update public.product_feedback set status='CLOSED'$$,'42501',null,'authenticated update denied');
select throws_ok($$delete from public.product_feedback$$,'42501',null,'authenticated delete denied');
reset role;
set local role service_role;
select lives_ok($$select message from public.product_feedback where id='b6000000-0000-4000-8000-000000000001'$$,'service read works');
select lives_ok($$update public.product_feedback set status='REVIEWED',version=version+1 where id='b6000000-0000-4000-8000-000000000001'$$,'service status update works');
select throws_ok($$insert into public.product_feedback(profile_id,kind,surface,message) values('b6000000-0000-4000-8000-000000000099','ISSUE','MERCHANT','bad FK')$$,'23503',null,'missing profile FK denied');
select throws_ok($$insert into public.product_feedback(profile_id,organization_id,kind,surface,message) values('55555555-5555-4555-8555-555555555551','b6000000-0000-4000-8000-000000000099','ISSUE','MERCHANT','bad FK')$$,'23503',null,'missing organization FK denied');
select throws_ok($$update public.product_feedback set kind='OTHER' where id='b6000000-0000-4000-8000-000000000001'$$,'23514',null,'kind check');
select throws_ok($$update public.product_feedback set surface='OTHER' where id='b6000000-0000-4000-8000-000000000001'$$,'23514',null,'surface check');
select throws_ok($$update public.product_feedback set status='OTHER' where id='b6000000-0000-4000-8000-000000000001'$$,'23514',null,'status check');
select throws_ok($$update public.product_feedback set version=0 where id='b6000000-0000-4000-8000-000000000001'$$,'23514',null,'version check');
select throws_ok($$update public.product_feedback set message=' ' where id='b6000000-0000-4000-8000-000000000001'$$,'23514',null,'empty message check');
select throws_ok($$update public.product_feedback set message=repeat('x',2001) where id='b6000000-0000-4000-8000-000000000001'$$,'22001',null,'message length check');
select throws_ok($$update public.product_feedback set expires_at=created_at+interval '91 days' where id='b6000000-0000-4000-8000-000000000001'$$,'23514',null,'retention check');
select lives_ok($$delete from public.product_feedback where id='b6000000-0000-4000-8000-000000000001'$$,'service can delete owned fixture');
reset role;
select * from finish();
rollback;
